const { subtle } = crypto;
const hex = (buffer) =>
  [...new Uint8Array(buffer)].map((b) => b.toString(16).padStart(2, "0")).join("");
const unhex = (text) => Uint8Array.from(text.match(/../g), (b) => parseInt(b, 16));
const bytes = (text) => new TextEncoder().encode(text);
const message = bytes("celld webcrypto vector");
const tampered = bytes("celld webcrypto vectoR");

function equal(actual, expected, what) {
  if (actual !== expected) throw new Error(`${what}: got ${actual}, want ${expected}`);
}

const aesKey = Uint8Array.from({ length: 16 }, (_, i) => i);
const iv = Uint8Array.from({ length: 16 }, (_, i) => 0xa0 + i);

// The same AES round trip for each mode: the ciphertext must match the
// reference, decrypt back to the message, and (for GCM) reject tampering.
async function aes(name, params) {
  const key = await subtle.importKey("raw", aesKey, name, true, ["encrypt", "decrypt"]);
  const sealed = await subtle.encrypt({ name, ...params }, key, message);
  equal(hex(sealed), V[name], "ciphertext");
  equal(hex(await subtle.decrypt({ name, ...params }, key, sealed)), hex(message), "plaintext");
  equal(hex(await subtle.exportKey("raw", key)), hex(aesKey), "exported key");
}

// Signature schemes: the reference signature must verify, a tampered message
// must not, and a signature made here must verify. Deterministic schemes
// must also reproduce the reference signature exactly.
async function signature(name, vector, params, deterministic) {
  const algorithm = { name, ...params };
  const priv = await subtle.importKey("pkcs8", unhex(vector.pkcs8), algorithm, true, ["sign"]);
  const pub = await subtle.importKey("spki", unhex(vector.spki), algorithm, true, ["verify"]);
  const reference = unhex(vector.signature);
  equal(await subtle.verify(algorithm, pub, reference, message), true, "reference verifies");
  equal(await subtle.verify(algorithm, pub, reference, tampered), false, "tampered verifies");
  const own = await subtle.sign(algorithm, priv, message);
  equal(await subtle.verify(algorithm, pub, own, message), true, "own signature verifies");
  if (deterministic) equal(hex(own), vector.signature, "signature");
  equal(hex(await subtle.exportKey("spki", pub)), vector.spki, "exported spki");
}

async function agreement(name, vector, params) {
  const algorithm = { name, ...params };
  const priv = await subtle.importKey("pkcs8", unhex(vector.pkcs8), algorithm, false, ["deriveBits"]);
  const peer = await subtle.importKey("spki", unhex(vector.peer), algorithm, true, []);
  const shared = await subtle.deriveBits({ name, public: peer }, priv, vector.length ?? 256);
  equal(hex(shared), vector.shared, "shared secret");
}


// Two generated pairs must not share a public key: a key generator that
// repeats its random material would otherwise pass every other check.
async function distinct(first, second) {
  const spki = async (pair) => hex(await subtle.exportKey("spki", pair.publicKey));
  equal((await spki(first)) === (await spki(second)), false, "two generated pairs are equal");
}

// A generated pair signs or encrypts and verifies or decrypts with itself,
// and its JWK, PKCS#8 and SPKI exports import back to a key that does the
// same.
async function generated(algorithm, kind) {
  const usages = kind === "oaep" ? ["encrypt", "decrypt"] : ["sign", "verify"];
  const pair = await subtle.generateKey(algorithm, true, usages);
  await distinct(pair, await subtle.generateKey(algorithm, true, usages));
  const use = async (priv, pub) => {
    if (kind === "oaep") {
      const sealed = await subtle.encrypt({ name: "RSA-OAEP" }, pub, message);
      equal(hex(await subtle.decrypt({ name: "RSA-OAEP" }, priv, sealed)), hex(message), "plaintext");
      return;
    }
    const params = algorithm.name === "ECDSA" ? { name: "ECDSA", hash: "SHA-512" } : algorithm.name === "RSA-PSS" ? { name: "RSA-PSS", saltLength: 32 } : algorithm.name;
    const sig = await subtle.sign(params, priv, message);
    equal(await subtle.verify(params, pub, sig, message), true, "verifies");
    equal(await subtle.verify(params, pub, sig, tampered), false, "tampered verifies");
  };
  await use(pair.privateKey, pair.publicKey);
  for (const [format, privFormat] of [["jwk", "jwk"], ["pkcs8", "spki"]]) {
    const priv = await subtle.importKey(
      format,
      await subtle.exportKey(format, pair.privateKey),
      algorithm,
      true,
      [kind === "oaep" ? "decrypt" : "sign"],
    );
    const pub = await subtle.importKey(
      privFormat,
      await subtle.exportKey(privFormat, pair.publicKey),
      algorithm,
      true,
      [kind === "oaep" ? "encrypt" : "verify"],
    );
    await use(priv, pub);
  }
}

async function generatedAgreement(algorithm) {
  const usages = ["deriveBits"];
  const a = await subtle.generateKey(algorithm, true, usages);
  const b = await subtle.generateKey(algorithm, true, usages);
  await distinct(a, b);
  const length = { "P-256": 256, "P-384": 384, "P-521": 528 }[algorithm.namedCurve] ?? 256;
  const ab = await subtle.deriveBits({ ...algorithm, public: b.publicKey }, a.privateKey, length);
  const ba = await subtle.deriveBits({ ...algorithm, public: a.publicKey }, b.privateKey, length);
  equal(hex(ab), hex(ba), "the two sides agree");
  // Each half survives export and import in each format, and the imported
  // keys still agree with the original secret.
  for (const [privFormat, pubFormat] of [["jwk", "jwk"], ["pkcs8", "spki"]]) {
    const priv = await subtle.importKey(privFormat, await subtle.exportKey(privFormat, a.privateKey), algorithm, true, usages);
    const pub = await subtle.importKey(pubFormat, await subtle.exportKey(pubFormat, b.publicKey), algorithm, true, []);
    equal(hex(await subtle.deriveBits({ ...algorithm, public: pub }, priv, length)), hex(ab), `after a ${privFormat} round trip`);
  }
}

